begin;
create extension if not exists pgcrypto with schema extensions;
create type public.tipo_local as enum ('consultorio','sala','quarto','leito');
create table public.empresas (id uuid primary key default gen_random_uuid(), razao_social text not null, nome_fantasia text not null, cnpj text not null unique check (cnpj ~ '^[0-9]{14}$'), ativo boolean not null default true, created_at timestamptz not null default now(), created_by uuid references auth.users, updated_at timestamptz not null default now(), updated_by uuid references auth.users);
create table public.unidades (id uuid primary key default gen_random_uuid(), empresa_id uuid not null references public.empresas, nome text not null, cnes text check (cnes is null or cnes ~ '^[0-9]{7}$'), timezone text not null default 'America/Sao_Paulo', ativo boolean not null default true, created_at timestamptz not null default now(), created_by uuid references auth.users, updated_at timestamptz not null default now(), updated_by uuid references auth.users, unique(empresa_id,nome));
create table public.setores (id uuid primary key default gen_random_uuid(), empresa_id uuid not null references public.empresas, unidade_id uuid not null references public.unidades, nome text not null, ativo boolean not null default true, created_at timestamptz not null default now(), created_by uuid references auth.users, updated_at timestamptz not null default now(), updated_by uuid references auth.users, unique(unidade_id,nome));
create table public.locais (id uuid primary key default gen_random_uuid(), empresa_id uuid not null references public.empresas, unidade_id uuid not null references public.unidades, setor_id uuid not null references public.setores, local_pai_id uuid references public.locais, tipo public.tipo_local not null, nome text not null, ativo boolean not null default true, created_at timestamptz not null default now(), created_by uuid references auth.users, updated_at timestamptz not null default now(), updated_by uuid references auth.users, unique(setor_id,tipo,nome));
create table public.usuarios (id uuid primary key references auth.users on delete restrict, nome text not null, bloqueado boolean not null default false, motivo_bloqueio text, ativo boolean not null default true, created_at timestamptz not null default now(), created_by uuid references auth.users, updated_at timestamptz not null default now(), updated_by uuid references auth.users);
create table public.permissoes (id uuid primary key default gen_random_uuid(), codigo text not null unique check (codigo ~ '^[a-z]+[a-z_.]+$'), descricao text not null, ativo boolean not null default true, created_at timestamptz not null default now(), created_by uuid references auth.users, updated_at timestamptz not null default now(), updated_by uuid references auth.users);
create table public.perfis (id uuid primary key default gen_random_uuid(), empresa_id uuid not null references public.empresas, nome text not null, sistema boolean not null default false, ativo boolean not null default true, created_at timestamptz not null default now(), created_by uuid references auth.users, updated_at timestamptz not null default now(), updated_by uuid references auth.users, unique(empresa_id,nome));
create table public.perfil_permissoes (perfil_id uuid not null references public.perfis on delete cascade, permissao_id uuid not null references public.permissoes on delete restrict, created_at timestamptz not null default now(), created_by uuid references auth.users, primary key(perfil_id,permissao_id));
create table public.usuario_empresas (id uuid primary key default gen_random_uuid(), usuario_id uuid not null references public.usuarios, empresa_id uuid not null references public.empresas, ativo boolean not null default true, created_at timestamptz not null default now(), created_by uuid references auth.users, updated_at timestamptz not null default now(), updated_by uuid references auth.users, unique(usuario_id,empresa_id));
create table public.usuario_unidades (id uuid primary key default gen_random_uuid(), usuario_id uuid not null references public.usuarios, empresa_id uuid not null references public.empresas, unidade_id uuid not null references public.unidades, ativo boolean not null default true, created_at timestamptz not null default now(), created_by uuid references auth.users, updated_at timestamptz not null default now(), updated_by uuid references auth.users, unique(usuario_id,unidade_id));
create table public.usuario_perfis (id uuid primary key default gen_random_uuid(), usuario_id uuid not null references public.usuarios, empresa_id uuid not null references public.empresas, unidade_id uuid references public.unidades, perfil_id uuid not null references public.perfis, ativo boolean not null default true, created_at timestamptz not null default now(), created_by uuid references auth.users, updated_at timestamptz not null default now(), updated_by uuid references auth.users, unique(usuario_id,perfil_id,unidade_id));
create table public.auditoria_eventos (id uuid primary key default gen_random_uuid(), empresa_id uuid not null references public.empresas, unidade_id uuid references public.unidades, usuario_id uuid not null references auth.users, operacao text not null, entidade text not null, registro_id uuid, origem text not null check (origem in ('web','api','job')), valores_anteriores jsonb, valores_novos jsonb, motivo text, correlation_id uuid not null, created_at timestamptz not null default now());
create index on public.unidades(empresa_id); create index on public.setores(empresa_id,unidade_id); create index on public.locais(empresa_id,unidade_id,setor_id); create index on public.usuario_empresas(usuario_id,empresa_id) where ativo; create index on public.usuario_unidades(usuario_id,unidade_id) where ativo; create index on public.usuario_perfis(usuario_id,empresa_id,unidade_id) where ativo; create index on public.auditoria_eventos(empresa_id,created_at desc);
create or replace function public.usuario_ativo() returns boolean language sql stable security invoker set search_path = '' as $$ select exists(select 1 from public.usuarios u where u.id=auth.uid() and u.ativo and not u.bloqueado) $$;
create or replace function public.tem_empresa(p_empresa uuid) returns boolean language sql stable security invoker set search_path = '' as $$ select public.usuario_ativo() and exists(select 1 from public.usuario_empresas ue where ue.usuario_id=auth.uid() and ue.empresa_id=p_empresa and ue.ativo) $$;
create or replace function public.tem_unidade(p_empresa uuid,p_unidade uuid) returns boolean language sql stable security invoker set search_path = '' as $$ select public.tem_empresa(p_empresa) and exists(select 1 from public.usuario_unidades uu where uu.usuario_id=auth.uid() and uu.empresa_id=p_empresa and uu.unidade_id=p_unidade and uu.ativo) $$;
create or replace function public.tem_permissao(p_empresa uuid,p_unidade uuid,p_codigo text) returns boolean language sql stable security invoker set search_path = '' as $$ select public.usuario_ativo() and exists(select 1 from public.usuario_perfis up join public.perfis pf on pf.id=up.perfil_id and pf.ativo join public.perfil_permissoes pp on pp.perfil_id=pf.id join public.permissoes pe on pe.id=pp.permissao_id and pe.ativo where up.usuario_id=auth.uid() and up.empresa_id=p_empresa and (up.unidade_id is null or up.unidade_id=p_unidade) and up.ativo and pe.codigo=p_codigo) $$;
do $$ declare t text; begin foreach t in array array['empresas','unidades','setores','locais','usuarios','permissoes','perfis','perfil_permissoes','usuario_empresas','usuario_unidades','usuario_perfis','auditoria_eventos'] loop execute format('alter table public.%I enable row level security',t); execute format('alter table public.%I force row level security',t); end loop; end $$;
create policy empresas_select on public.empresas for select using (public.tem_empresa(id));
create policy unidades_select on public.unidades for select using (public.tem_unidade(empresa_id,id));
create policy setores_select on public.setores for select using (public.tem_unidade(empresa_id,unidade_id));
create policy locais_select on public.locais for select using (public.tem_unidade(empresa_id,unidade_id));
create policy perfis_select on public.perfis for select using (public.tem_empresa(empresa_id));
create policy usuario_empresas_select on public.usuario_empresas for select using (usuario_id=auth.uid() and public.usuario_ativo());
create policy usuario_unidades_select on public.usuario_unidades for select using (usuario_id=auth.uid() and public.usuario_ativo());
create policy usuario_perfis_select on public.usuario_perfis for select using (usuario_id=auth.uid() and public.usuario_ativo());
create policy usuarios_self_select on public.usuarios for select using (id=auth.uid() and ativo and not bloqueado);
create policy permissoes_authenticated_select on public.permissoes for select to authenticated using (public.usuario_ativo());
create policy perfil_permissoes_select on public.perfil_permissoes for select using (exists(select 1 from public.perfis p where p.id=perfil_id and public.tem_empresa(p.empresa_id)));
create policy auditoria_select on public.auditoria_eventos for select using (public.tem_permissao(empresa_id,unidade_id,'auditoria.visualizar'));
create policy auditoria_insert on public.auditoria_eventos for insert with check (usuario_id=auth.uid() and public.tem_empresa(empresa_id) and (unidade_id is null or public.tem_unidade(empresa_id,unidade_id)));
revoke update,delete,truncate on public.auditoria_eventos from anon,authenticated;
insert into public.permissoes(codigo,descricao) values ('empresas.visualizar','Visualizar empresas'),('empresas.administrar','Administrar empresas'),('estrutura.visualizar','Visualizar estrutura'),('estrutura.criar','Criar estrutura'),('estrutura.editar','Editar estrutura'),('usuarios.visualizar','Visualizar usuários'),('usuarios.vincular','Vincular usuários'),('usuarios.administrar','Administrar usuários'),('pacientes.visualizar','Visualizar pacientes'),('pacientes.criar','Criar pacientes'),('pacientes.editar','Editar pacientes'),('atendimentos.visualizar','Visualizar atendimentos'),('atendimentos.abrir','Abrir atendimento'),('atendimentos.transferir','Transferir atendimento'),('atendimentos.alta','Registrar alta'),('triagem.registrar','Registrar triagem'),('prontuario.visualizar','Visualizar prontuário'),('prontuario.evoluir','Evoluir prontuário'),('prescricao.criar','Criar prescrição'),('prescricao.suspender','Suspender prescrição'),('faturamento.visualizar','Visualizar faturamento'),('faturamento.fechar','Fechar faturamento'),('auditoria.visualizar','Visualizar auditoria');
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values
('documentos-pacientes','documentos-pacientes',false,10485760,array['application/pdf','image/jpeg','image/png']),('prontuarios','prontuarios',false,10485760,array['application/pdf']),('documentos-medicos','documentos-medicos',false,10485760,array['application/pdf']),('resultados-laudos','resultados-laudos',false,26214400,array['application/pdf','image/jpeg','image/png']),('anexos-autorizacao','anexos-autorizacao',false,10485760,array['application/pdf','image/jpeg','image/png']),('anexos-faturamento','anexos-faturamento',false,10485760,array['application/pdf','text/xml']),('glosas-recursos','glosas-recursos',false,10485760,array['application/pdf','text/xml']);
-- Objetos usam caminho empresa_uuid/unidade_uuid/uuid; leitura exige ambos os vínculos.
create policy storage_clinico_select on storage.objects for select to authenticated using (bucket_id in ('documentos-pacientes','prontuarios','documentos-medicos','resultados-laudos','anexos-autorizacao','anexos-faturamento','glosas-recursos') and public.tem_unidade(((storage.foldername(name))[1])::uuid,((storage.foldername(name))[2])::uuid));
create policy storage_clinico_insert on storage.objects for insert to authenticated with check (bucket_id in ('documentos-pacientes','prontuarios','documentos-medicos','resultados-laudos','anexos-autorizacao','anexos-faturamento','glosas-recursos') and array_length(storage.foldername(name),1)=2 and public.tem_unidade(((storage.foldername(name))[1])::uuid,((storage.foldername(name))[2])::uuid) and (storage.filename(name) ~ '^[0-9a-f-]{36}$'));
commit;
